from fastapi import FastAPI, Header
from fastapi.testclient import TestClient
import pytest

app = FastAPI()

@app.get("/test")
async def test_endpoint(my_header: str = Header(...)):
    return {"my_header": my_header}

client = TestClient(app)

def test_header_underscores_default():
    # Default convert_underscores=True. Should NOT accept my_header, should accept my-header.
    # But currently it accepts my_header.
    response = client.get("/test", headers={"my_header": "value_underscore"})
    assert response.status_code == 422, "Should not accept header with underscore by default"

def test_header_hyphen_default():
    # Default convert_underscores=True. Should accept my-header.
    response = client.get("/test", headers={"my-header": "value_hyphen"})
    assert response.status_code == 200
    assert response.json() == {"my_header": "value_hyphen"}

@app.get("/test_disabled")
async def test_endpoint_disabled(my_header: str = Header(..., convert_underscores=False)):
    return {"my_header": my_header}

def test_header_underscores_disabled():
    # convert_underscores=False. Should accept my_header.
    response = client.get("/test_disabled", headers={"my_header": "value_underscore"})
    assert response.status_code == 200
    assert response.json() == {"my_header": "value_underscore"}

def test_header_hyphen_disabled():
    # convert_underscores=False. Should NOT accept my-header (unless it's also my_header).
    response = client.get("/test_disabled", headers={"my-header": "value_hyphen"})
    assert response.status_code == 422
